def solve(n):
    # n is the number of boxes, each with 1 marble.
    # We'll represent the state as a sorted tuple of marble counts.
    states = set()
    initial_state = tuple(sorted([1] * n))
    states.add(initial_state)

    queue = [initial_state]
    visited = {initial_state}

    min_boxes = n

    idx = 0
    while idx < len(queue):
        curr = queue[idx]
        idx += 1

        if len(curr) < min_boxes:
            min_boxes = len(curr)

        if len(curr) == 1:
            return 1

        # Try all possible moves
        for i in range(len(curr)):
            for j in range(i + 1, len(curr)):
                a, b = curr[i], curr[j]
                for k in range(1, min(a, b) + 1):
                    # New state: remove a, b, and add a-k, b-k, 2k
                    new_list = list(curr)
                    new_list.pop(j) # pop j first to not affect i
                    new_list.pop(i)
                    if a - k > 0:
                        new_list.append(a - k)
                    if b - k > 0:
                        new_list.append(b - k)
                    new_list.append(2 * k)
                    new_state = tuple(sorted(new_list))

                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append(new_state)
    return min_boxes

for i in range(1, 11):
